121	        HttpHeaders headers = new HttpHeaders();
122	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
123	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
124	        if (owner.getRegistrationDate() == null) {
125	            owner.setRegistrationDate(LocalDate.now());
126	        }
127	        if (isDailyRegistrationLimitReached()) {
128	            throw new DailyOwnerRegistrationLimitException(
129	                "The maximum of " + MAX_OWNERS_PER_DAY
130	                    + " owners that may be registered today has already been reached");
131	        }
132	        if (isDuplicateTelephone(owner)) {
133	            throw new DuplicateOwnerException("An owner with telephone "
134	                + owner.getTelephone() + " already exists");
135	        }
136	        if (isDuplicateEmail(owner)) {
137	            throw new DuplicateOwnerException("An owner with email "
138	                + owner.getEmail() + " already exists");
139	        }
140	        if (isCityOwnerLimitReached(owner.getCity())) {
141	            throw new CityOwnerLimitException("The city " + owner.getCity()
142	                + " already contains the maximum of " + MAX_OWNERS_PER_CITY + " owners");
143	        }
144	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
145	        owner.setCity(resolveCity(owner.getCity()));
146	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
147	        this.clinicService.saveOwner(owner);
148	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
149	        headers.setLocation(UriComponentsBuilder.newInstance()
150	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
