154	    /**
155	     * Determines whether the maximum number of owner registrations permitted for today has
156	     * already been reached. Owners are counted by registration date, comparing against the
157	     * current day, so the limit resets at midnight.
158	     *
159	     * @return {@code true} if at least {@link #MAX_OWNERS_PER_DAY} owners already carry today's
160	     *         registration date
161	     */
162	    private boolean isDailyRegistrationLimitReached() {
163	        LocalDate today = LocalDate.now();
164	        long registeredToday = this.clinicService.findAllOwners().stream()
165	            .filter(existing -> today.equals(existing.getRegistrationDate()))
166	            .count();
167	        return registeredToday >= MAX_OWNERS_PER_DAY;
168	    }
