170	    /**
171	     * Determines whether the given city already contains the maximum number of owners permitted
172	     * per city. Owners are counted by matching their city ignoring letter case. A {@code null}
173	     * city is never considered to have reached the limit.
174	     *
175	     * @param city the city of the owner about to be created
176	     * @return {@code true} if at least {@link #MAX_OWNERS_PER_CITY} owners already reside in the
177	     *         given city
178	     */
179	    private boolean isCityOwnerLimitReached(String city) {
180	        if (city == null) {
181	            return false;
182	        }
183	        long ownersInCity = this.clinicService.findAllOwners().stream()
184	            .filter(existing -> existing.getCity() != null
185	                && existing.getCity().equalsIgnoreCase(city))
186	            .count();
