194	     * @param candidate the owner about to be created
195	     * @return {@code true} if an owner with the same telephone is already present in the data store
196	     */
197	    private boolean isDuplicateTelephone(Owner candidate) {
198	        String telephone = normalizeTelephone(candidate.getTelephone());
199	        return this.clinicService.findAllOwners().stream()
200	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
