203	    /**
204	     * Canonicalises a telephone number by stripping every character that is not a digit
205	     * (for example spaces, dashes and parentheses), so that {@code "(613) 555-0100"} and
206	     * {@code "6135550100"} are treated as the same number. This is the form persisted for
207	     * an owner and used for the telephone-uniqueness check.
208	     *
209	     * @param telephone the raw telephone value, possibly {@code null}
210	     * @return the digits-only telephone, or {@code null} if {@code telephone} was {@code null}
211	     */
212	    private static String normalizeTelephone(String telephone) {
213	        if (telephone == null) {
214	            return null;
215	        }
216	        return telephone.replaceAll("[^0-9]", "");
217	    }
