219	    /**
220	     * Determines whether any other owner already uses the candidate's email address.
221	     * An absent or blank email is never considered a duplicate. The comparison ignores
222	     * letter case and surrounding or repeated whitespace.
223	     *
224	     * @param candidate the owner about to be created
225	     * @return {@code true} if an owner with the same email is already present in the data store
226	     */
227	    private boolean isDuplicateEmail(Owner candidate) {
228	        String email = normalize(candidate.getEmail());
229	        if (email == null || email.isBlank()) {
230	            return false;
231	        }
232	        return this.clinicService.findAllOwners().stream()
233	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
234	    }
