236	    /**
237	     * Builds the customer code for a newly created owner, formatted as
238	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of
239	     * owners already present in the same city, zero-padded to four digits
240	     * (e.g. {@code 'LONDON-0007'}). Cities are matched ignoring letter case.
241	     *
242	     * @param city the city of the owner about to be created
243	     * @return the formatted customer code
244	     */
245	    /**
246	     * Resolves the city name to store for a newly created owner. The supplied city is
247	     * normalised to title case (each word's first letter upper-cased, the rest lower-cased),
248	     * so that {@code "new york"} and {@code "NEW YORK"} both become {@code "New York"}.
249	     * However, if an owner already exists in that city (matched ignoring letter case), that
250	     * existing owner's exact spelling of the city is reused instead, so a single canonical
251	     * spelling is kept per city (for example an existing {@code "McFarland"} is preserved
252	     * rather than being flattened to {@code "Mcfarland"}).
253	     *
254	     * @param city the raw city supplied for the owner about to be created
255	     * @return the existing owner's spelling if the city is already known, otherwise the
256	     *         title-cased city; {@code null} if {@code city} was {@code null}
257	     */
258	    private String resolveCity(String city) {
259	        if (city == null) {
260	            return null;
261	        }
262	        return this.clinicService.findAllOwners().stream()
263	            .map(Owner::getCity)
264	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
265	            .findFirst()
266	            .orElseGet(() -> titleCase(city));
267	    }
268	
269	    /**
270	     * Converts a city name to title case: each whitespace-separated word has its first letter
271	     * upper-cased and its remaining letters lower-cased, while the original whitespace is left
272	     * untouched. For example {@code "san   FRANCISCO"} becomes {@code "San   Francisco"}.
273	     *
274	     * @param city the city to title-case
275	     * @return the title-cased city
276	     */
277	    private static String titleCase(String city) {
278	        StringBuilder result = new StringBuilder(city.length());
279	        boolean startOfWord = true;
280	        for (int i = 0; i < city.length(); i++) {
281	            char c = city.charAt(i);
282	            if (Character.isWhitespace(c)) {
283	                startOfWord = true;
284	                result.append(c);
285	            } else if (startOfWord) {
286	                result.append(Character.toTitleCase(c));
287	                startOfWord = false;
288	            } else {
289	                result.append(Character.toLowerCase(c));
290	            }
291	        }
292	        return result.toString();
293	    }
