295	    private String nextCustomerCode(String city) {
296	        long ownersInCity = this.clinicService.findAllOwners().stream()
297	            .filter(existing -> existing.getCity() != null
298	                && existing.getCity().equalsIgnoreCase(city))
299	            .count();
300	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
301	    }
