303	    /**
304	     * Canonicalises a value for duplicate detection so that comparisons ignore letter
305	     * case and surrounding or repeated whitespace. Surrounding whitespace is stripped,
306	     * any run of internal whitespace is collapsed to a single space, and the result is
307	     * lower-cased. For example {@code "  john   smith "} and {@code "John Smith"} both
308	     * normalise to {@code "john smith"}.
309	     *
310	     * @param value the raw value, possibly {@code null}
311	     * @return the normalised value, or {@code null} if {@code value} was {@code null}
312	     */
313	    private static String normalize(String value) {
314	        if (value == null) {
315	            return null;
316	        }
317	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
318	    }
